167	    pub fn query_by_session(&self, session_id: &str) -> Result<Vec<ProvenanceRecord>> {
168	        let mut stmt = self.conn.prepare(
169	            "SELECT id, session_id, timestamp_ms, file_path, code_hash, model_id,
170	                    model_version, contributor_type, start_line, end_line,
171	                    attestation_sig, developer_id, prompt_hash, project_dir
172	             FROM provenance_records
173	             WHERE session_id = ?1
174	             ORDER BY timestamp_ms ASC",
175	        )?;
176	        let rows = stmt
177	            .query_map(params![session_id], |row| {
178	                Ok(ProvenanceRecord {
179	                    id: Some(row.get(0)?),
180	                    session_id: row.get(1)?,
181	                    timestamp_ms: row.get(2)?,
182	                    file_path: row.get(3)?,
183	                    code_hash: row.get(4)?,
184	                    model_id: row.get(5)?,
185	                    model_version: row.get(6)?,
186	                    contributor_type: ContributorType::from_str(
187	                        &row.get::<_, String>(7)?,
188	                    ),
189	                    start_line: row.get(8)?,
190	                    end_line: row.get(9)?,
191	                    attestation_sig: row.get(10)?,
192	                    developer_id: row.get(11)?,
193	                    prompt_hash: row.get(12)?,
194	                    project_dir: row.get(13)?,
195	                })
196	            })?
197	            .collect::<Result<Vec<_>, _>>()?;
198	        Ok(rows)
199	    }
