23	    fn test_hash_content_deterministic() {
24	        let h1 = hash_content(b"hello world");
25	        let h2 = hash_content(b"hello world");
26	        assert_eq!(h1, h2);
27	        assert_eq!(h1.len(), 64);
28	    }
29	
30	    #[test]
31	    fn test_hash_content_different_inputs() {
