49	pub fn to_agent_trace(record: &ProvenanceRecord) -> TraceEntry {
50	    let ts = chrono::DateTime::from_timestamp_millis(record.timestamp_ms)
51	        .map(|dt| dt.to_rfc3339())
52	        .unwrap_or_else(|| record.timestamp_ms.to_string());
53	
54	    TraceEntry {
55	        timestamp: ts,
56	        file_path: record.file_path.clone(),
57	        code_hash: record.code_hash.clone(),
58	        contributor: TraceContributor {
59	            contributor_type: record.contributor_type.as_str().to_string(),
60	            model_id: record.model_id.clone(),
61	            model_version: record.model_version.clone(),
62	            developer_id: record.developer_id.clone(),
63	        },
64	        lines: TraceLineRange {
65	            start: record.start_line,
66	            end: record.end_line,
67	        },
68	        attestation: TraceAttestation {
69	            algorithm: "ed25519".to_string(),
70	            signature: record.attestation_sig.clone(),
71	        },
72	        session_id: record.session_id.clone(),
73	    }
74	}
