127	        .with_env_filter(EnvFilter::from_default_env())
128	        .with_writer(std::io::stderr)
129	        .init();
130	
131	    let cli = Cli::parse();
132	
133	    let result = match cli.command {
134	        Commands::Init { global } => hooks::install(global),
135	        Commands::Uninit { global } => hooks::uninstall(global),
136	        Commands::Wrap { command } => wrap::execute(&command),
137	        Commands::Stats { json, days, waste } => stats::show(json, days, waste),
138	        Commands::Sync { once, api_url } => {
139	            let mut config = sync::SyncConfig { one_shot: once, ..Default::default() };
140	            if let Some(url) = api_url {
141	                config.api_url = url;
142	            }
143	            sync::run(config)
144	        }
145	        Commands::Login { auth_url } => auth::login(auth_url.as_deref()),
146	        Commands::Status => auth::status(),
147	        Commands::Logout => auth::logout(),
148	        Commands::Route { command, tokens, files } => handle_route(&command, tokens, &files),
149	
150	        Commands::Blame { file, json, session, trace } => {
151	            handle_blame(&file, json, session.as_deref(), trace)
152	        }
153	        Commands::Cache { action } => handle_cache(action),
154	        Commands::Hook { action } => handle_hook(action),
155	        Commands::Update => {
156	            println!("codeflow {}", env!("CARGO_PKG_VERSION"));
157	            println!("commit:  {}", option_env!("CODEFLOW_GIT_SHA").unwrap_or("dev"));
158	            println!("target:  {}", env!("TARGET"));
159	            println!();
160	            println!("Update: download latest from https://github.com/codeflow-dev/codeflow/releases");
161	            Ok(())
162	        }
163	    };
164	
165	    if let Err(e) = result {
166	        tracing::error!("{:#}", e);
167	        std::process::exit(1);
168	    }
