254	fn handle_route(command: &str, tokens: u64, files: &[String]) -> anyhow::Result<()> {
255	    let cmd = command.to_string();
256	    if cmd.is_empty() {
257	        anyhow::bail!("no command provided");
258	    }
259	
260	    let file_refs: Vec<&str> = files.iter().map(|f| f.as_str()).collect();
261	    let extensions = codeflow_core::router::extensions_from_paths(&file_refs);
262	
263	    let input = codeflow_core::router::RoutingInput {
264	        command: cmd.clone(),
265	        context_tokens: tokens,
266	        file_extensions: extensions,
267	        session_event_count: 0,
268	    };
269	
270	    let decision = codeflow_core::router::classify(&input);
271	
272	    println!("Command:    {}", cmd);
273	    println!("Tokens:     {}", tokens);
274	    println!("Score:      {:.2}", decision.score);
275	    println!("Complexity: {:?}", decision.complexity);
276	    println!("Route to:   {} (${}/1M tokens)", decision.tier.name(), decision.tier.cost_per_million_tokens());
277	    println!("Savings:    {:.0}% vs Opus", decision.estimated_savings_pct);
278	    if !decision.reason.is_empty() {
279	        println!("Reason:     {}", decision.reason);
280	    }
281	
282	    Ok(())
283	}
