319	fn capture_provenance(
320	    session_id: &str,
321	    tool_name: &str,
322	    tool_input: &serde_json::Value,
323	) -> anyhow::Result<()> {
324	    let db_path = paths::db_path();
325	    let store = codeflow_core::provenance::ProvenanceStore::open(&db_path)?;
326	    let keypair = codeflow_core::attestation::load_or_generate()?;
327	    let project_dir = std::env::current_dir().unwrap_or_default();
328	
329	    // Step 1: diff against previous snapshots → record provenance for prior tool's changes
330	    let changes = codeflow_core::provenance::detect_changes(
331	        &project_dir,
332	        session_id,
333	        &store,
334	        &keypair,
335	    )?;
336	    for rec in &changes {
337	        store.record(rec)?;
338	        // Update snapshot to current state after recording
339	        if let Ok(hash) = codeflow_core::content_hash::hash_file(&project_dir.join(&rec.file_path)) {
340	            let mtime = codeflow_core::util::get_file_mtime_ns(
341	                project_dir.join(&rec.file_path).to_str().unwrap_or(""),
342	            )
343	            .unwrap_or(0);
344	            store.save_snapshot(session_id, &rec.file_path, &hash, mtime)?;
345	        }
346	    }
347	
348	    // Step 2: snapshot files targeted by the current tool for next comparison
349	    let files_to_snapshot = extract_target_files(tool_name, tool_input, &project_dir);
350	    if !files_to_snapshot.is_empty() {
351	        codeflow_core::provenance::snapshot_files(
352	            &project_dir,
353	            session_id,
354	            &store,
355	            &files_to_snapshot,
356	        )?;
357	    }
358	
359	    Ok(())
360	}
