362	fn extract_target_files(
363	    tool_name: &str,
364	    tool_input: &serde_json::Value,
365	    project_dir: &std::path::Path,
366	) -> Vec<String> {
367	    let mut files = Vec::new();
368	    match tool_name {
369	        "Edit" | "Write" | "MultiEdit" | "NotebookEdit" => {
370	            if let Some(fp) = tool_input.get("file_path").and_then(|v| v.as_str()) {
371	                if let Some(rel) = to_relative(fp, project_dir) {
372	                    files.push(rel);
373	                }
374	            }
375	        }
376	        "Bash" => {
377	            // Bash can modify files; we can't know which ones ahead of time.
378	            // Snapshot tracked files that git reports as modified after the command runs.
379	            // Since PreToolUse fires BEFORE execution, we can only snapshot what's
380	            // already tracked. The diff-on-next-PreToolUse pattern handles detection.
381	        }
382	        _ => {}
383	    }
384	    files
385	}
