421	        println!("{{}}");
422	        return Ok(());
423	    }
424	
425	    let tool_name = match parsed.get("tool_name").and_then(|v| v.as_str()) {
426	        Some(name) => name,
427	        None => {
428	            println!("{{}}");
429	            return Ok(());
430	        }
431	    };
432	
433	    let tool_input = match parsed.get("tool_input") {
434	        Some(v) if v.is_object() => v,
435	        _ => {
436	            println!("{{}}");
437	            return Ok(());
438	        }
439	    };
440	
441	    // Log to session + dedup check (single connection, best-effort)
442	    let session_id = codeflow_core::util::session_id();
443	    let file_path = codeflow_core::session::extract_file_path(tool_name, tool_input);
444	    let session_log = open_session_log(&session_id).ok();
445	
446	    if let Some(ref sl) = session_log {
447	        let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
448	        if let Ok(row_id) =
449	            sl.record_pre(tool_name, &tool_input_str, file_path.as_deref())
450	        {
451	            sl.write_pre_id(tool_name, file_path.as_deref(), row_id);
452	        }
453	    }
454	
455	    if std::env::var("CODEFLOW_PROVENANCE").as_deref() != Ok("0") {
456	        let _ = capture_provenance(&session_id, tool_name, tool_input);
457	    }
458	
459	    match tool_name {
460	        "Bash" => {
461	            if let Some(command) = tool_input.get("command").and_then(|c| c.as_str()) {
462	                if should_wrap(command) {
463	                    let codeflow_bin = std::env::current_exe()
464	                        .map(|p| p.to_string_lossy().to_string())
465	                        .unwrap_or_else(|_| "codeflow".to_string());
466	                    let quoted_bin = shell_quote(&codeflow_bin);
467	                    let rewritten = format!("{} wrap {}", quoted_bin, command);
468	                    let response = serde_json::json!({
469	                        "tool_input": {
470	                            "command": rewritten
471	                        }
472	                    });
473	                    println!("{}", serde_json::to_string(&response)?);
474	                    return Ok(());
475	                }
476	            }
477	            println!("{{}}");
478	        }
479	        "Read" | "Grep" | "Glob" => {
480	            if let Some(ref session_log) = session_log {
481	                let window_secs = std::env::var("CODEFLOW_DEDUP_WINDOW_SECS")
482	                    .ok()
483	                    .and_then(|v| v.parse().ok());
484	                let dedup =
485	                    codeflow_core::read_dedup::ReadDedup::new(session_log, window_secs);
486	                let tool_input_str = serde_json::to_string(tool_input).unwrap_or_default();
487	
488	                let result = match tool_name {
489	                    "Read" => {
490	                        if let Some(fp) = file_path.as_deref() {
491	                            dedup.check_read(fp)
492	                        } else {
493	                            codeflow_core::read_dedup::ReadDedupResult::Miss
494	                        }
495	                    }
496	                    "Grep" => dedup.check_grep(&tool_input_str),
497	                    "Glob" => dedup.check_glob(&tool_input_str),
498	                    _ => codeflow_core::read_dedup::ReadDedupResult::Miss,
499	                };
500	
501	                match result {
502	                    codeflow_core::read_dedup::ReadDedupResult::Hit {
503	                        context_message,
504	                        tokens_saved,
505	                    } => {
506	                        let response = serde_json::json!({
507	                            "additionalContext": context_message
508	                        });
509	                        println!("{}", serde_json::to_string(&response).unwrap_or_default());
510	
511	                        // Track savings
512	                        if tokens_saved > 0 {
513	                            if let Ok(tracking) =
514	                                codeflow_core::tracking::TrackingDb::open(&paths::db_path())
515	                            {
516	                                let _ = tracking.record(
517	                                    &codeflow_core::tracking::TrackingEvent {
518	                                        command: tool_name.to_string(),
519	                                        input_tokens: tokens_saved,
520	                                        output_tokens: 0,
521	                                        tokens_saved,
522	                                        layer:
523	                                            codeflow_core::tracking::SavingsLayer::ReadDedup,
524	                                        project: std::env::current_dir()
525	                                            .unwrap_or_default()
526	                                            .to_string_lossy()
527	                                            .to_string(),
528	                                        session_id: session_id.clone(),
529	                                    },
530	                                );
531	                            }
532	                        }
533	                        return Ok(());
534	                    }
535	                    codeflow_core::read_dedup::ReadDedupResult::Miss => {
536	                        println!("{{}}");
537	                    }
538	                }
539	            } else {
540	                println!("{{}}");
541	            }
542	        }
543	        _ => {
544	            println!("{{}}");
545	        }
546	    }
547	
548	    Ok(())
549	}
