560	    let parsed: serde_json::Value = serde_json::from_str(&input).unwrap_or_default();
561	    let tool_name = parsed.get("tool_name").and_then(|v| v.as_str());
562	    let tool_result = parsed
563	        .get("tool_result")
564	        .and_then(|v| v.as_str())
565	        .unwrap_or("");
566	
567	    if let Some(tn) = tool_name {
568	        if matches!(tn, "Read" | "Grep" | "Glob" | "Bash") {
569	            let file_path = parsed
570	                .get("tool_input")
571	                .and_then(|ti| codeflow_core::session::extract_file_path(tn, ti));
572	
573	            let session_id = codeflow_core::util::session_id();
574	            if let Ok(session_log) = open_session_log(&session_id) {
575	                if let Some(row_id) = session_log.take_pre_id(tn, file_path.as_deref()) {
576	                    let capped = if tool_result.len() > 1_048_576 {
577	                        &tool_result[..1_048_576]
578	                    } else {
579	                        tool_result
580	                    };
581	                    let content_hash =
582	                        blake3::hash(capped.as_bytes()).to_hex().to_string();
583	                    let token_count = codeflow_core::util::estimate_tokens(tool_result.len()) as i64;
584	
585	                    let mtime_ns =
586	                        file_path.as_deref().and_then(codeflow_core::util::get_file_mtime_ns);
587	
588	                    let _ = session_log.record_post(
589	                        row_id,
590	                        &content_hash,
591	                        token_count,
592	                        mtime_ns,
593	                    );
594	                }
595	            }
596	        }
597	    }
598	
599	    println!("{{}}");
600	    Ok(())
601	}
