614	fn should_wrap(command: &str) -> bool {
615	    let first_word = command.split_whitespace().next().unwrap_or("");
616	    let stem = std::path::Path::new(first_word)
617	        .file_stem()
618	        .and_then(|s| s.to_str())
619	        .unwrap_or(first_word);
620	    let wrappable = [
621	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
622	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
623	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy", "vitest",
624	    ];
625	    wrappable.contains(&stem)
626	}
